@startuml

class User {
  + FullName : string
}

class UnderAgedUser extends User {
  + StudentCard : string
}

class AdultUser extends User {
  + IDCard : string
}

class Book {
  + Title : string
  + Author : string
}

class BorrowingHistory {
  + BorrowDate : date
  + ReturnDate : date
}

User "1" -- "0..4" Book : borrows
User "1" -- "0..*" BorrowingHistory : has
BorrowingHistory "0..*" -- "1" Book : includes

@enduml

